(() => {
  if (typeof window === 'undefined') return
  if (window.Tesseract) return

  window.Tesseract = {
    async createWorker() {
      return {
        async recognize(canvasLike) {
          const width = canvasLike?.width ?? 0
          const height = canvasLike?.height ?? 0
          return {
            data: {
              text: width > 0 && height > 0 ? '' : ''
            }
          }
        },
        async terminate() {}
      }
    }
  }
})()
